	'in_journal_04' => 'Verwitterte Hände legen im Streiflicht ein Tau um eine Stahlklampe.',
	'in_journal_05' => 'Journal',
	'in_journal_06' => 'Notizen vom Kai: vier Beiträge in Hafennotizen und Saison, verschlagwortet mit Stege, Treibstoff, Gäste und Winter. Der vollständige Winterbeitrag steht unten.',
	'in_newsletter_01' => 'Newsletter',
